        CYC(24 + ((t8 != 0) ? 1 : 0));
        if (t8 != 0) goto l_grlzcl_92;               /* LA4AA  B EXIT SINCE BUNKER ALREADY DAMAGED */
        D = 0x0690;                                  /* LA4AE  DOUBLE BUNKER HITE */
        wr16(M_YP, D);                               /* LA4B1 */
        D = 0x05A0;                                  /* LA4B4  DOUBLE BUNKER HITE */
