    A = MS_PERS;                                     /* LA4C8 */
    CYC(16);
    JSR(mgowt);                                      /* LA4CA  DO THE MULTIPLYS */
    D = rd16(M_YT);                                  /* LA4CD  NOW TEST UNROTATED VIDEO LOC */
    D = (uint16_t)(D + rd16(M_YP));                  /* LA4D0  MISNAMED, IS RADIUS OF COLLISION */
    D = (uint16_t)(D + 0x000A);                      /* LA4D3  SITE RADIUS FOR FUDGE */
    D = sub16(D, rd16(0+M_X0));                      /* LA4D6  UNROTATED LAZAR SITE LOCATION */
    /* IFGE ;1?TO ONE SIDE OF TOWER? */
    CYC(29 + (((CCN ^ CCV)) ? 1 : 0));
